function updateRoomTypesList(card, o){
  const h=findHotel(o.hotelName, o.hotelId);
  let rooms=[];
  if(h && h.rates){
    rooms=[...new Set(h.rates.map(r=>r.roomType).filter(Boolean))];
  }
  if(!rooms.length){
    rooms=[...new Set(HOTELS.flatMap(h=>(h.rates||[]).map(r=>r.roomType)).filter(Boolean))];
  }
  const listId=`roomTypes_${o.id}`;
  let listEl=document.body.querySelector(`#${listId}`);
  if(!listEl){
    listEl=document.createElement('datalist');
    listEl.id=listId;
    document.body.appendChild(listEl);
  }
  listEl.innerHTML=rooms.map(v=>`<option value="${esc(v)}"></option>`).join('');
}

function updateOfferCardSummary(card,o){
  const s=stats(o);
  const summary=card.querySelectorAll('.summary span');
  if(summary[0])summary[0].textContent=o.hasMultiplePeriods?`إجمالي: ${nightsText(s.nights)} (${s.periods.map((period,index)=>`ف${index+1}: ${period.nights}`).join(' · ')})`:nightsText(s.nights);
  if(summary[1])summary[1].textContent=`WEEKDAY: ${s.weekday}`;
  if(summary[2])summary[2].textContent=`WEEKEND: ${s.weekend}`;
  if(summary[3])summary[3].textContent=`الغرف: ${s.rooms}`;
  // Update per-room total row (second-to-last .option-total)
  const allTotals=card.querySelectorAll('.option-total');
  const grandTotalEl=allTotals[allTotals.length-1];
  const perRoomEl=allTotals.length>1?allTotals[allTotals.length-2]:null;
  if(grandTotalEl){
    const b=grandTotalEl.querySelector('b');
    const sp=grandTotalEl.querySelector('span');
    if(b)b.textContent=`${money(s.total)} ${app.draft.currency}`;
    if(sp)sp.textContent=`إجمالي هذا الخيار${s.rooms>1?` (${s.rooms} غرف)`:''}`;
  }
  if(perRoomEl&&s.rooms>1){
    const b=perRoomEl.querySelector('b');
    if(b)b.textContent=`${money(s.totalPerRoom)} ${app.draft.currency}`;
  }
  // If rooms dropped to 1, do a full re-render to remove the per-room row
  if(s.rooms<=1&&allTotals.length>1){card.querySelector('.option-total[style*="3a5c38"]')?.remove();}
}

function updateCostingSummary(card,o){
  const currency=app.draft.currency,sale=stats(o),bestId=bestSupplierQuoteId(o);
  const saleReference=card.querySelector('.sale-reference');
  if(saleReference){
    const total=saleReference.querySelector('b'),detail=saleReference.querySelector('small');
    if(total)total.textContent=`${money(sale.total)} ${currency}`;
    if(detail)detail.textContent=`${money(sale.totalPerRoom)} للغرفة × ${sale.rooms} غرف`;
  }
  (o.supplierQuotes||[]).forEach(quote=>{
    const el=card.querySelector(`[data-supplier-card="${quote.id}"]`);
    if(!el)return;
    const calculated=supplierCostStats(o,quote),ready=calculated.complete;
    const metric=value=>ready?`${money(value)} ${currency}`:'—';
    el.classList.toggle('best-supplier',quote.id===bestId);
    const badge=el.querySelector('[data-best-supplier]');
    if(badge)badge.hidden=quote.id!==bestId;
    const status=el.querySelector('[data-cost-status]');
    if(status){
      status.textContent=ready?'اكتملت أسعار التكلفة لهذه الشركة.':'أدخل سعر التكلفة لكل فترة ليظهر الربح بدقة.';
      status.classList.toggle('complete',ready);
      status.classList.toggle('incomplete',!ready);
    }
    const values={
      '[data-cost-per-room]':metric(calculated.totalPerRoom),
      '[data-cost-total]':metric(calculated.total),
      '[data-profit]':metric(calculated.profit),
      '[data-margin]':ready?`${percent(calculated.margin)}%`:'—'
    };
    Object.entries(values).forEach(([selector,value])=>{const target=el.querySelector(selector);if(target)target.textContent=value});
    ['[data-profit-metric]','[data-margin-metric]'].forEach(selector=>{
      const target=el.querySelector(selector);
      if(!target)return;
      target.classList.remove('profit-positive','profit-negative');
      if(ready)target.classList.add(calculated.profit>=0?'profit-positive':'profit-negative');
    });
    calculated.periods.forEach(period=>{
      const row=el.querySelector(`[data-cost-period-row="${period.periodId}"]`);
      const subtotal=row?.querySelector('[data-cost-period-subtotal]');
      if(subtotal)subtotal.textContent=period.complete?`${money(period.totalPerRoom)} ${currency}`:'—';
    });
  });
}

function renderOffers(){
  const wrap=document.getElementById('offers');
  if(!wrap)return;
  // Clean up unused roomTypes datalists
  const activeIds=new Set(app.draft.items.map(o=>`roomTypes_${o.id}`));
  document.querySelectorAll('datalist[id^="roomTypes_"]').forEach(el=>{
    if(!activeIds.has(el.id))el.remove();
  });
  wrap.innerHTML=app.draft.items.map(offerHtml).join('');
  wrap.querySelectorAll('[data-id]').forEach(card=>{
    const o=app.draft.items.find(x=>x.id===card.dataset.id);
    if(!o)return;
    updateRoomTypesList(card, o);

    const refresh=(updateClientOutput=true)=>{
      clearTimeout(saveTimer);
      syncSupplierCostPeriods(o);
      persist();
      renderOffers();
      if(updateClientOutput){
        renderPreview();
        renderGrandTotalPreview();
      }
    };
    const commitClientFields=()=>{
      clearTimeout(saveTimer);
      persist();
      updateOfferCardSummary(card,o);
      updateCostingSummary(card,o);
      renderPreview();
      renderGrandTotalPreview();
    };
    
    const mode=card.querySelector('[data-hotel-mode]');
    if(mode)mode.addEventListener('change',()=>{
      o.hotelMode=mode.value;
      o.hotelId='';
      o.hotelName='';
      if(o.hotelMode==='custom'){
        (o.periods||[]).forEach(period=>{period.nightlyPrice='';period.weekdayPrice='';period.weekendPrice='';period.totalPrice=''});
        (o.supplierQuotes||[]).forEach(quote=>(quote.periods||[]).forEach(period=>{period.nightlyPrice='';period.weekdayPrice='';period.weekendPrice='';period.totalPrice=''}));
        o.extraBed='';
      }
      refresh();
    });

    const hotelSelect=card.querySelector('[data-hotel-select]');
    if(hotelSelect)hotelSelect.addEventListener('change',()=>{
      const selected=hotelSelect.value;
      o.hotelId=selected;
      o.hotelName='';
      if(selected&&applyHotel(o,selected)){
        applyRate(o);
        toast('تم اختيار الفندق وتحديث الأسعار المتاحة');
      }
      refresh();
    });

    const customHotel=card.querySelector('[data-hotel-custom]');
    if(customHotel){
      customHotel.addEventListener('input',()=>{o.hotelMode='custom';o.hotelId='';o.hotelName=customHotel.value;autoSave()});
      customHotel.addEventListener('change',()=>{o.hotelName=customHotel.value.trim();persist();renderPreview()});
    }

    card.querySelectorAll('[data-key]').forEach(el=>{
      const key=el.dataset.key;
      if(el.tagName!=='SELECT')el.addEventListener('input',()=>{
        o[key]=el.value;
        updateOfferCardSummary(card,o);
        updateCostingSummary(card,o);
        autoSave();
      });
      el.addEventListener('change',()=>{
        o[key]=el.value;
        if(key==='roomType')applyRate(o);
        if(['pricingMode','roomType','roomCount'].includes(key))refresh();
        else commitClientFields();
      });
    });

    const multipleToggle=card.querySelector('[data-multiple-periods]');
    if(multipleToggle)multipleToggle.addEventListener('change',()=>{
      o.hasMultiplePeriods=multipleToggle.checked;
      if(o.hasMultiplePeriods&&o.periods.length<2)o.periods.push(nextPeriodAfter(o.periods[0]));
      syncSupplierCostPeriods(o);
      refresh();
    });

    card.querySelectorAll('[data-period-key]').forEach(el=>{
      const period=o.periods.find(item=>item.id===el.dataset.periodId);
      if(!period)return;
      const key=el.dataset.periodKey;
      el.addEventListener('input',()=>{
        period[key]=el.value;
        updateOfferCardSummary(card,o);
        updateCostingSummary(card,o);
        autoSave();
      });
      el.addEventListener('change',()=>{
        period[key]=el.value;
        if(key==='checkIn'&&period.checkOut&&period.checkOut<=period.checkIn)period.checkOut=addDaysISO(period.checkIn,1);
        if(key==='checkIn')applyRateToPeriod(o,period,true);
        refresh();
      });
    });

    const addPeriodBtn=card.querySelector('[data-add-period]');
    if(addPeriodBtn)addPeriodBtn.onclick=()=>{
      const period=nextPeriodAfter(o.periods[o.periods.length-1]);
      o.periods.push(period);
      o.hasMultiplePeriods=true;
      applyRateToPeriod(o,period,true);
      syncSupplierCostPeriods(o);
      refresh();
      toast(`تمت إضافة ${periodLabel(o.periods.length-1)}`);
    };

    card.querySelectorAll('[data-remove-period]').forEach(btn=>btn.onclick=()=>{
      if(o.periods.length<=2){toast('يجب وجود فترتين على الأقل عند تفعيل التقسيم');return}
      const index=o.periods.findIndex(period=>period.id===btn.dataset.removePeriod);
      if(index<0)return;
      if(!confirm(`حذف ${periodLabel(index)} وأسعار التكلفة المرتبطة بها؟`))return;
      o.periods.splice(index,1);
      syncSupplierCostPeriods(o);
      refresh();
    });

    const costDetails=card.querySelector('[data-cost-details]');
    if(costDetails)costDetails.addEventListener('toggle',()=>{
      o.costingOpen=costDetails.open;
      persist();
    });

    const addSupplierBtn=card.querySelector('[data-add-supplier]');
    if(addSupplierBtn)addSupplierBtn.onclick=()=>{
      o.supplierQuotes.push(defaultSupplierQuote(o.periods));
      o.costingOpen=true;
      refresh(false);
      toast('تمت إضافة شركة أخرى للمقارنة');
    };

    card.querySelectorAll('[data-remove-supplier]').forEach(btn=>btn.onclick=()=>{
      if(o.supplierQuotes.length<=1){toast('يجب وجود خانة شركة واحدة على الأقل');return}
      const quote=o.supplierQuotes.find(item=>item.id===btn.dataset.removeSupplier);
      if(!quote)return;
      if(!confirm(`حذف سعر ${quote.companyName||'هذه الشركة'}؟`))return;
      o.supplierQuotes=o.supplierQuotes.filter(item=>item.id!==quote.id);
      o.costingOpen=true;
      refresh(false);
    });

    card.querySelectorAll('[data-supplier-key]').forEach(el=>el.addEventListener('input',()=>{
      const quote=o.supplierQuotes.find(item=>item.id===el.dataset.supplierId);
      if(!quote)return;
      quote[el.dataset.supplierKey]=el.value;
      persist();
    }));

    card.querySelectorAll('[data-cost-key]').forEach(el=>el.addEventListener('input',()=>{
      const quote=o.supplierQuotes.find(item=>item.id===el.dataset.supplierId);
      const period=quote?.periods.find(item=>item.periodId===el.dataset.costPeriodId);
      if(!period)return;
      period[el.dataset.costKey]=el.value;
      persist();
      updateCostingSummary(card,o);
    }));
  });

  wrap.querySelectorAll('[data-move-up]').forEach(btn=>btn.onclick=()=>moveOfferUp(btn.dataset.moveUp));
  wrap.querySelectorAll('[data-move-down]').forEach(btn=>btn.onclick=()=>moveOfferDown(btn.dataset.moveDown));
  wrap.querySelectorAll('[data-copy-offer]').forEach(btn=>btn.onclick=()=>duplicateOffer(btn.dataset.copyOffer));

  wrap.querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=()=>{
    if(app.draft.items.length===1){toast('يجب وجود خيار واحد على الأقل');return}
    app.draft.items=app.draft.items.filter(x=>x.id!==btn.dataset.remove);
    persist();
    renderAll();
  });
}

function periodPriceText(o,period,pStats,currency){
  if(o.pricingMode==='weekdayWeekend'){
    return`وسط الأسبوع: ${money(period.weekdayPrice)} ${currency} × ${pStats.weekday} · ويك إند: ${money(period.weekendPrice)} ${currency} × ${pStats.weekend}`;
  }
  if(o.pricingMode==='total')return`السعر الكامل: ${money(period.totalPrice)} ${currency}`;
  return`سعر الليلة: ${money(period.nightlyPrice)} ${currency}`;
}

function previewPrice(o,s){
  const periods=activePeriods(o),period=periods[0]||defaultPeriod();
  if(periods.length>1)return`إجمالي ${periods.length} فترات (${nightsText(s.nights)})`;
  if(o.pricingMode==='weekdayWeekend')return`وسط الأسبوع: ${money(period.weekdayPrice)} × ${s.weekday} · نهاية الأسبوع: ${money(period.weekendPrice)} × ${s.weekend}`;
  if(o.pricingMode==='total')return`السعر الكامل للمدة: ${money(period.totalPrice)} ${esc(app.draft.currency)}`;
  return`سعر الليلة: ${money(period.nightlyPrice)} ${esc(app.draft.currency)}`;
}

function grandTotalHtml(q){
  if(!q.showGrandTotal)return'';
  const items=q.items||[];
  const grandTotal=items.reduce((sum,o)=>sum+stats(o).total,0);
  const totalRooms=items.reduce((sum,o)=>sum+Math.max(1,num(o.roomCount)||1),0);
  const roomGroups={};
  items.forEach(o=>{
    const roomCount=Math.max(1,num(o.roomCount)||1);
    const label=o.roomType&&o.roomType.trim()?o.roomType.trim():'غرفة';
    roomGroups[label]=(roomGroups[label]||0)+roomCount;
  });
  const breakdownParts=Object.entries(roomGroups).map(([type,count])=>`${count} ${esc(type)}`).join(' + ');
  return`<div class="grand-total-block" style="margin-top:14px;border:2.5px solid #dfb667;border-radius:14px;overflow:hidden;break-inside:avoid">
    <div style="background:linear-gradient(130deg,#4a0617,#6b0d24);color:#f4d690;padding:10px 16px;font-family:'GESSTwo','ExpoArabic',Tahoma,Arial,sans-serif;font-weight:700;font-size:14px;display:flex;justify-content:space-between;align-items:center">
      <span>الإجمالي الكلي</span>
      <span style="font-size:11px;opacity:0.85">جميع الخيارات</span>
    </div>
    <div style="padding:12px 16px;background:#fffdf9">
      <div style="margin-bottom:8px;font-size:13px;color:#583640">
        <b>العدد الإجمالي للغرف:</b> ${totalRooms} غرفة
      </div>
      <div style="margin-bottom:10px;font-size:12px;color:#7c636b;padding:7px 10px;background:#f7edf0;border-radius:8px">${breakdownParts}</div>
      <div style="display:flex;justify-content:space-between;align-items:center;border-top:2px solid #dfb667;padding-top:10px">
        <span style="font-size:13px;color:#583640;font-weight:700">الإجمالي الكلي لجميع الخيارات</span>
        <span style="font-family:'HelveticaRounded','HelveticaBold','ExpoArabic',Tahoma,Arial,sans-serif;font-size:20px;font-weight:700;color:#6b0d24">${money(grandTotal)} ${esc(q.currency)}</span>
      </div>
    </div>
  </div>`;
}

function grandTotalTextBlock(q){
  if(!q.showGrandTotal)return'';
  const items=q.items||[];
  const grandTotal=items.reduce((sum,o)=>sum+stats(o).total,0);
  const totalRooms=items.reduce((sum,o)=>sum+Math.max(1,num(o.roomCount)||1),0);
  const roomGroups={};
  items.forEach(o=>{
    const roomCount=Math.max(1,num(o.roomCount)||1);
    const label=o.roomType&&o.roomType.trim()?o.roomType.trim():'غرفة';
    roomGroups[label]=(roomGroups[label]||0)+roomCount;
  });
  const breakdownParts=Object.entries(roomGroups).map(([type,count])=>`${count} ${type}`).join(' + ');
  return[
    '─────────────────────',
    `العدد الإجمالي للغرف: ${totalRooms} غرفة`,
    `التفاصيل: ${breakdownParts}`,
    `الإجمالي الكلي لجميع الخيارات: ${money(grandTotal)} ${q.currency}`,
    '─────────────────────'
  ].join('\n');
}


function previewGreetingHtml(q){
  return`<div class="greeting">عزيزي العميل / <b>${esc(q.customerName||'اسم العميل')}</b><br>${esc(q.intro)}</div>`;
}

function previewClosingHtml(q){
  return`<div class="closing"><b>${esc(q.notes)}</b><br>${esc(q.closing)}</div>`;
}

function previewOfferHtml(o,globalIndex,q){
  const st=stats(o),periods=activePeriods(o),first=periods[0]||defaultPeriod();
  const isLast=globalIndex===q.items.length-1;
  const extraBedStr=num(o.extraBed)>0?`<br><small>السرير الإضافي: ${money(o.extraBed)} ${esc(q.currency)}</small>`:'';
  const notesStr=o.notes?`<br><small>${esc(o.notes)}</small>`:'';
  const roomsLabel=st.rooms>1?`<div class="detail" style="background:#fff8ea;border-color:#e8c97a"><b>عدد الغرف</b><span>${st.rooms}</span></div>`:'';
  const perRoomLine=st.rooms>1?`
      <div class="price-line" style="border-top:none;padding-top:0;margin-top:6px;opacity:0.8">
        <span style="font-size:12px">إجمالي الغرفة الواحدة</span>
        <b style="font-size:14px;color:#8a6f77">${money(st.totalPerRoom)} ${esc(q.currency)}</b>
      </div>`:'';
  const totalLineStyle=st.rooms>1?'border-top:2px solid var(--gold);padding-top:8px;margin-top:4px;':'';
  const grandTotalSection=isLast?grandTotalHtml(q):'';
  const periodsBlock=periods.length>1?`<div class="preview-periods">${periods.map((period,index)=>{
    const calculated=st.periods[index]||calculatePeriodStats(period.checkIn,period.checkOut,o.pricingMode,period);
    return`<div class="preview-period-row"><span class="preview-period-label">${periodLabel(index)}</span><span class="preview-period-dates">من ${dateLabel(period.checkIn)} إلى ${dateLabel(period.checkOut)} · ${nightsText(calculated.nights)}</span><span class="preview-period-pricing">${esc(periodPriceText(o,period,calculated,q.currency))}</span><b>${money(calculated.totalPerRoom)} ${esc(q.currency)}</b></div>`;
  }).join('')}</div>`:'';
  return`<section class="preview-offer" data-offer-index="${globalIndex}">
    <div class="preview-offer-head"><span>${q.items.length>1?`الخيار ${globalIndex+1}`:`تفاصيل الإقامة`}</span><span>${nightsText(st.nights)}${st.rooms>1?` · ${st.rooms} غرف`:''}</span></div>
    <div class="preview-offer-body">
      <div class="hotel-name">${esc(o.hotelName||'اسم الفندق')}</div>
      <div class="detail-grid">
        ${periods.length===1?`<div class="detail"><b>الدخول</b><span>${dateLabel(first.checkIn)}</span></div><div class="detail"><b>الخروج</b><span>${dateLabel(first.checkOut)}</span></div>`:''}
        <div class="detail"><b>الغرفة</b><span>${esc(o.roomType||'—')}</span></div>
        <div class="detail"><b>الوجبة</b><span>${esc(o.mealPlan||'—')}</span></div>
        <div class="detail"><b>الإطلالة</b><span>${esc(o.view||'—')}</span></div>
        <div class="detail"><b>توزيع الليالي</b><span>${st.weekday} وسط الأسبوع · ${st.weekend} ويك إند</span></div>
        ${roomsLabel}
      </div>
      ${periodsBlock}
      ${perRoomLine}
      <div class="price-line" style="${totalLineStyle}">
        <span>${st.rooms>1?`<b>الإجمالي الكلي (${st.rooms} غرف)</b>`:previewPrice(o,st)}${st.rooms>1?`<br><small>${previewPrice(o,st)} × ${st.rooms}</small>`:''}${extraBedStr}${notesStr}</span>
        <b>${money(st.total)} ${esc(q.currency)}</b>
      </div>
    </div>
    ${grandTotalSection}
  </section>`;
}

function outerHeight(el){
  if(!el)return 0;
  const style=getComputedStyle(el);
  return el.getBoundingClientRect().height+(parseFloat(style.marginTop)||0)+(parseFloat(style.marginBottom)||0);
}

const DENSITY_MODES=['spacious','normal','compact','dense','micro'];

function getInitialDensity(count){
  if(count<=1)return'spacious';
  if(count===2)return'normal';
  if(count===3)return'compact';
  if(count<=5)return'dense';
  return'micro';
}

function measurePreviewLayout(q,sets,density){
  const probe=document.createElement('div');
  probe.className='quote-measure-root';
  probe.setAttribute('aria-hidden','true');
  probe.innerHTML=`<article class="quote-page quote-measure-page" data-density="${density}">
    <header class="quote-header">
      <img src="${window.ORIGINAL_LOGO}" alt="">
      <div class="quote-title"><h1>عرض سعر للعميل</h1><p>تفاصيل الإقامة والحجز المقترح</p></div>
      <div class="quote-date"><b>التاريخ</b><br>${dateLabel(q.quoteDate)}</div>
    </header>
    <main class="quote-body">
      <div class="measure-greeting">${previewGreetingHtml(q)}</div>
      <div class="measure-offers">${q.items.map((o,i)=>previewOfferHtml(o,i,q)).join('')}</div>
      <div class="measure-closing">${previewClosingHtml(q)}</div>
    </main>
    <footer class="quote-footer">
      <div class="phones" dir="ltr">${phoneList().map(p=>`<span class="phone-number" dir="ltr">${esc(p)}</span>`).join('')}</div>
      <div class="company-line">${esc(sets.companyName)} · ${esc(sets.companyLine)}</div>
    </footer>
  </article>`;
  document.body.appendChild(probe);
  const page=probe.querySelector('.quote-page');
  const header=probe.querySelector('.quote-header');
  const body=probe.querySelector('.quote-body');
  const footer=probe.querySelector('.quote-footer');
  const bodyStyle=getComputedStyle(body);
  const pageHeight=page.getBoundingClientRect().height||1123;
  const bottomReserve=Math.max(parseFloat(bodyStyle.paddingBottom)||0,(footer?.getBoundingClientRect().height||0)+20);
  const contentLimit=Math.max(100,pageHeight-header.getBoundingClientRect().height-(parseFloat(bodyStyle.paddingTop)||0)-bottomReserve-4);
  const greetingHeight=outerHeight(probe.querySelector('.greeting'));
  const offerHeights=[...probe.querySelectorAll('.preview-offer')].map(outerHeight);
  const closingHeight=outerHeight(probe.querySelector('.closing'));
  probe.remove();
  return{contentLimit,greetingHeight,offerHeights,closingHeight};
}

function doPaginateWithDensity(q,sets,density){
  const measured=measurePreviewLayout(q,sets,density);
  const pages=[];
  const heights=[];
  const newPage=()=>{pages.push([]);heights.push(measured.greetingHeight)};
  newPage();

  q.items.forEach((offer,index)=>{
    const offerHeight=measured.offerHeights[index]||0;
    let pageIndex=pages.length-1;
    if(pages[pageIndex].length&&heights[pageIndex]+offerHeight>measured.contentLimit){
      newPage();
      pageIndex=pages.length-1;
    }
    pages[pageIndex].push({offer,index});
    heights[pageIndex]+=offerHeight;
  });

  let last=pages.length-1;
  if(heights[last]+measured.closingHeight>measured.contentLimit){
    const tail=[];
    let tailHeight=measured.greetingHeight+measured.closingHeight;
    while(pages[last].length){
      const candidate=pages[last][pages[last].length-1];
      const candidateHeight=measured.offerHeights[candidate.index]||0;
      if(tailHeight+candidateHeight>measured.contentLimit)break;
      pages[last].pop();
      heights[last]-=candidateHeight;
      tail.unshift(candidate);
      tailHeight+=candidateHeight;
    }
    if(tail.length){
      if(!pages[last].length){pages.pop();heights.pop()}
      pages.push(tail);
      heights.push(tailHeight-measured.closingHeight);
    }else{
      pages.push([]);
      heights.push(measured.greetingHeight);
    }
  }
  return pages;
}

function paginatePreviewItems(q,sets){
  const count=(q.items||[]).length;
  const initialDensity=getInitialDensity(count);
  const startIdx=DENSITY_MODES.indexOf(initialDensity);

  let chosenPages=[];
  let chosenDensity=initialDensity;

  for(let i=startIdx;i<DENSITY_MODES.length;i++){
    chosenDensity=DENSITY_MODES[i];
    chosenPages=doPaginateWithDensity(q,sets,chosenDensity);
    if(chosenPages.length<=2)break; // Always fit within max 2 pages!
  }

  return{chunks:chosenPages,density:chosenDensity};
}

function renderPreview(){
  const q=app.draft,sets=app.settings;
  const {chunks,density}=paginatePreviewItems(q,sets);
  const totalPages=chunks.length;

  const pages=chunks.map((chunk,pageIndex)=>{
    const items=chunk.map(({offer,index})=>previewOfferHtml(offer,index,q)).join('');
    const finalBlock=pageIndex===totalPages-1?previewClosingHtml(q):'';
    return`<div class="quote-page-wrapper">
    <article class="quote-page" data-density="${density}">
      <header class="quote-header">
        <img src="${window.ORIGINAL_LOGO}" alt="شعار الشركة">
        <div class="quote-title"><h1>عرض سعر للعميل</h1><p>تفاصيل الإقامة والحجز المقترح</p></div>
        <div class="quote-date"><b>التاريخ</b><br>${dateLabel(q.quoteDate)}</div>
      </header>
      <main class="quote-body">
        ${previewGreetingHtml(q)}
        ${items}
        ${finalBlock}
      </main>
      ${totalPages>1?`<div dir="ltr" style="position:absolute;bottom:82px;left:28px;color:#8a6f77;font-size:11px;direction:ltr;unicode-bidi:isolate">${pageIndex+1} / ${totalPages}</div>`:''}
      <footer class="quote-footer">
        <div class="phones" dir="ltr">${phoneList().map(p=>`<span class="phone-number" dir="ltr">${esc(p)}</span>`).join('')}</div>
        <div class="company-line">${esc(sets.companyName)} · ${esc(sets.companyLine)}</div>
      </footer>
    </article></div>`;
  }).join('');

  const pagesContainer = document.getElementById('quotePages');
  if(pagesContainer) pagesContainer.innerHTML=pages;

  const densityBadge=document.getElementById('densityBadge');
  if(densityBadge){
    const densityNames={
      spacious:'خط كبير (خيار واحد)',
      normal:'خط قياسي',
      compact:'خط مدمج',
      dense:'خط مكثف',
      micro:'خط دقيق'
    };
    densityBadge.textContent=`${totalPages} ${totalPages>1?'صفحات':'صفحة'} (${densityNames[density]||density})`;
  }
  
  const logoEl = document.getElementById('brandLogo');
  if(logoEl) logoEl.src=sets.logo||ORIGINAL_LOGO;
  
  const titleEl = document.getElementById('appTitle');
  if(titleEl) titleEl.textContent=`${sets.companyName} | عرض سعر للأفراد`;

  updatePreviewScale();
}

function updatePreviewScale(){
  const stage = document.querySelector('.preview-stage');
  if(!stage) return;
  const stageWidth = stage.clientWidth - 28;
  if(window.innerWidth <= 1050 && stageWidth > 0){
    const scale = Math.min(1, Math.max(0.3, stageWidth / 794));
    document.documentElement.style.setProperty('--preview-scale', scale.toFixed(3));
  } else {
    document.documentElement.style.setProperty('--preview-scale', '1');
  }
}
window.addEventListener('resize', updatePreviewScale);

function normalizePhone(value){let p=String(value||'').trim().replace(/\s+/g,'');if(p.endsWith('+')&&!p.startsWith('+'))p='+'+p.slice(0,-1);return p}
function normalizePhones(value){return String(value||'').split(/[،,|]+/).map(normalizePhone).filter(Boolean).join('، ')}
function phoneList(){return normalizePhones(app.settings.phones||'').split('،').map(x=>x.trim()).filter(Boolean)}

function bindRoot(){
  [['customerName','customerName'],['quoteDate','quoteDate'],['currency','currency'],['intro','intro'],['notes','notes'],['closing','closing']].forEach(([id,key])=>{
    const el=document.getElementById(id);
    if(!el)return;
    el.value=app.draft[key]||'';
    el.oninput=()=>{app.draft[key]=el.value;autoSave()};
  });
}

function saveCurrent(silent=false){
  const title=[app.draft.customerName||'عرض عميل',app.draft.items[0]?.hotelName||'',dateLabel(app.draft.quoteDate)].filter(Boolean).join(' - ');
  const now=new Date().toISOString();
  const item={id:uid(),title,data:clone(app.draft),createdAt:now,updatedAt:now};
  app.library.unshift(item);
  app.activeId=item.id;
  app.library=app.library.slice(0,250);
  persist();
  renderSaved();
  if(!silent) toast('تم حفظ عرض السعر');
}

function loadSaved(id){
  const x=app.library.find(x=>x.id===id);
  if(!x)return;
  app.draft=clone(x.data);
  app.activeId=x.id;
  persist();
  renderAll();
  scrollTo({top:0,behavior:'smooth'});
  toast('تم فتح العرض');
}

function deleteSaved(id){
  const x=app.library.find(x=>x.id===id);
  if(!x)return;
  if(!confirm(`حذف ${x.title}؟`))return;
  app.library=app.library.filter(x=>x.id!==id);
  if(app.activeId===id)app.activeId='';
  persist();
  renderSaved();
  toast('تم الحذف');
}

function duplicateSaved(id){
  const x=app.library.find(x=>x.id===id);
  if(!x)return;
  const now=new Date().toISOString();
  app.library.unshift({...clone(x),id:uid(),title:`${x.title} - نسخة`,createdAt:now,updatedAt:now});
  persist();
  renderSaved();
  toast('تم إنشاء نسخة');
}

function renderSaved(){
  const wrap=document.getElementById('savedList');
  if(!wrap)return;
  if(!app.library.length){wrap.innerHTML='<div class="empty">لا توجد عروض محفوظة بعد.</div>';return}
  wrap.innerHTML=[...app.library].sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).map(x=>`<div class="saved-item"><div class="saved-meta"><b>${esc(x.title)}</b><small>${new Date(x.updatedAt).toLocaleString('ar-EG')}</small></div><div class="saved-actions"><button class="btn primary small" data-open="${x.id}">فتح</button><button class="btn light small" data-copy="${x.id}">نسخة</button><button class="btn danger small" data-delete="${x.id}">حذف</button></div></div>`).join('');
  wrap.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>loadSaved(b.dataset.open));
  wrap.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>duplicateSaved(b.dataset.copy));
  wrap.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteSaved(b.dataset.delete));
}

function newDraft(){
  if(!confirm('بدء عرض جديد؟ سيتم الاحتفاظ بالعروض المحفوظة.'))return;
  app.draft=defaultData().draft;
  app.activeId='';
  persist();
  renderAll();
  toast('تم إنشاء عرض جديد');
}

function clearDraft(confirmReset=true){
  if(confirmReset && !confirm('مسح جميع البيانات والبدء بعرض جديد؟')) return;
  app.draft=defaultData().draft;
  app.activeId='';
  persist();
  renderAll();
  toast('تم مسح البيانات والبدء بعرض جديد');
}

function quoteText(){
  const q=app.draft,lines=[`عزيزي العميل / ${q.customerName||'................'}`,q.intro,''];
  q.items.forEach((o,i)=>{
    const s=stats(o),periods=activePeriods(o),first=periods[0]||defaultPeriod();
    if(q.items.length > 1) lines.push(`الخيار ${i+1}:`);
    lines.push(`الفندق: ${o.hotelName||'—'}`);
    if(periods.length>1){
      periods.forEach((period,index)=>{
        const periodStats=s.periods[index];
        lines.push(
          `${periodLabel(index)}: من ${dateLabel(period.checkIn)} إلى ${dateLabel(period.checkOut)} (${nightsText(periodStats.nights)})`,
          `سعر ${periodLabel(index)}: ${periodPriceText(o,period,periodStats,q.currency)}`
        );
      });
      lines.push(
        `إجمالي عدد الليالي: ${nightsText(s.nights)}`,
        `نوع الغرفة: ${o.roomType||'—'}`,
        `نوع الوجبة: ${o.mealPlan||'—'}`,
        `الإطلالة: ${o.view||'—'}`,
        `عدد الغرف: ${s.rooms}`
      );
    }else{
      lines.push(
        `الدخول: ${dateLabel(first.checkIn)}`,
        `الخروج: ${dateLabel(first.checkOut)}`,
        `نوع الغرفة: ${o.roomType||'—'}`,
        `نوع الوجبة: ${o.mealPlan||'—'}`,
        `الإطلالة: ${o.view||'—'}`,
        `عدد الليالي: ${nightsText(s.nights)}`,
        `عدد الغرف: ${s.rooms}`
      );
      if(o.pricingMode==='weekdayWeekend')
        lines.push(`سعر وسط الأسبوع: ${money(first.weekdayPrice)} ${q.currency} × ${s.weekday}`,`سعر نهاية الأسبوع: ${money(first.weekendPrice)} ${q.currency} × ${s.weekend}`);
      else if(o.pricingMode==='total')
        lines.push(`السعر الكامل للمدة: ${money(first.totalPrice)} ${q.currency}`);
      else
        lines.push(`سعر الليلة: ${money(first.nightlyPrice)} ${q.currency}`);
    }
    
    if(num(o.extraBed)>0)
      lines.push(`سعر السرير الإضافي: ${money(o.extraBed)} ${q.currency}`);
    
    if(s.rooms>1){
      lines.push(`إجمالي الغرفة الواحدة: ${money(s.totalPerRoom)} ${q.currency}`);
      lines.push(`× ${s.rooms} غرف`);
      lines.push(`الإجمالي الكلي: ${money(s.total)} ${q.currency}`);
    } else {
      lines.push(`الإجمالي: ${money(s.total)} ${q.currency}`);
    }
    if(o.notes)
      lines.push(`ملاحظات: ${o.notes}`);
    lines.push('');
  });
  lines.push(q.notes,q.closing,'',`للتواصل: ${phoneList().join(' | ')}`);
  if(q.showGrandTotal){
    const gtBlock=grandTotalTextBlock(q);
    if(gtBlock)lines.splice(lines.length-3,0,'',gtBlock);
  }
  return lines.join('\n');
}

async function copyQuote(){
  saveCurrent(true);
  const text=quoteText();
  try{await navigator.clipboard.writeText(text)}
  catch(e){
    const t=document.createElement('textarea');
    t.value=text;
    document.body.appendChild(t);
    t.select();
    document.execCommand('copy');
    t.remove();
  }
  toast('تم نسخ الرسالة وحفظ العرض');
}

function exportBackup(){
  const blob=new Blob([JSON.stringify(app,null,2)],{type:'application/json'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=`yanabea-quotes-backup-${today()}.json`;
  a.click();
  setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}

function importBackup(file){
  if(!file||file.size>5*1024*1024){alert('حجم ملف النسخة الاحتياطية غير مسموح');return}
  const r=new FileReader();
  r.onload=()=>{
    try{
      const data=JSON.parse(String(r.result||''));
      if(!data||typeof data!=='object'||!data.draft||typeof data.draft!=='object'||!Array.isArray(data.library))throw Error();
      app=data;
      normalize();
      persist();
      renderAll();
      toast('تم استيراد النسخة الاحتياطية');
    }catch(e){alert('ملف النسخة الاحتياطية غير صالح')}
  };
  r.onerror=()=>alert('تعذر قراءة ملف النسخة الاحتياطية');
  r.readAsText(file);
}

function renderSettings(){
  const nameInput = document.getElementById('companyName');
  if(nameInput) nameInput.value=app.settings.companyName||'';
  const lineInput = document.getElementById('companyLine');
  if(lineInput) lineInput.value=app.settings.companyLine||'';
  const phonesInput=document.getElementById('phones');
  if(phonesInput){
    phonesInput.dir='ltr';
    phonesInput.value=normalizePhones(app.settings.phones||'');
  }
  const fonts=pdfFontState();
  Object.entries(PDF_FONT_SPECS).forEach(([key,spec])=>{
    const el=document.getElementById(spec.nameId);
    if(el)el.textContent=fonts[key]?.name||`مدمج داخل المشروع: ${spec.builtInFile}`;
  });
  bindPdfFontControls();
}

function saveSettings(){
  app.settings.companyName=document.getElementById('companyName').value.trim()||'ينابيع الهدى المتميزة';
  app.settings.companyLine=document.getElementById('companyLine').value.trim()||'سكن مطمئن لرحلة مباركة';
  app.settings.phones=normalizePhones(document.getElementById('phones').value);
  persist();
  renderSettings();
  renderPreview();
  toast('تم حفظ الإعدادات');
}

function buildLists(){
  const hotels=HOTELS.map(h=>h.name);
  const rooms=[...new Set(HOTELS.flatMap(h=>(h.rates||[]).map(r=>r.roomType)).filter(Boolean))];
  const meals=[...new Set(HOTELS.map(h=>h.mealPlan).filter(Boolean))];
  const views=['إطلالة الحرم','إطلالة الكعبة','إطلالة المدينة','إطلالة جزئية','بدون إطلالة','حسب المتاح'];
  [['hotelNames',hotels],['roomTypes',rooms],['mealPlans',meals],['views',views]].forEach(([id,list])=>{
    const el=document.getElementById(id);
    if(el)el.innerHTML=list.map(v=>`<option value="${esc(v)}"></option>`).join('');
  });
}

function renderGrandTotalPreview(){
  const preview=document.getElementById('grandTotalPreview');
  const previewText=document.getElementById('grandTotalPreviewText');
  const cb=document.getElementById('grandTotalToggle');
  if(!preview||!previewText||!cb)return;
  const checked=cb.checked;
  preview.classList.toggle('visible',checked);
  if(checked){
    previewText.value=grandTotalTextBlock(app.draft);
  }
}

function renderAll(){
  normalize();
  bindRoot();
  renderOffers();
  renderPreview();
  renderSaved();
  renderSettings();
  // Sync grand total checkbox state with current draft
  const _gtCb=document.getElementById('grandTotalToggle');
  if(_gtCb)_gtCb.checked=!!(app.draft.showGrandTotal);
  renderGrandTotalPreview();
}


function updateScale(){
  const stage=document.querySelector('.preview-stage');
  if(!stage)return;
  const availableWidth=stage.clientWidth - 16;
  if(availableWidth<=0)return;
  const scale=availableWidth<794?Math.max(0.2, (availableWidth / 794)):1;
  document.documentElement.style.setProperty('--preview-scale',scale.toFixed(4));
}

function setMobileTab(tab){
  const e=document.getElementById('editorColumn'),p=document.getElementById('previewColumn');
  if(!e||!p)return;
  e.classList.toggle('mobile-hidden',tab==='preview');
  p.classList.toggle('mobile-hidden',tab!=='preview');
  if(tab==='preview'){setTimeout(updateScale,30);setTimeout(updateScale,150);}
  if(tab==='saved'){
    e.classList.remove('mobile-hidden');
    setTimeout(()=>document.getElementById('savedPanel')?.scrollIntoView({behavior:'smooth'}),20);
  }
  if(tab==='settings'){
    e.classList.remove('mobile-hidden');
    setTimeout(()=>document.getElementById('settingsPanel')?.scrollIntoView({behavior:'smooth'}),20);
  }
  document.querySelectorAll('[data-mobile-tab]').forEach(b=>b.classList.toggle('active',b.dataset.mobileTab===tab));
}

function init(){
  normalize();
  buildLists();
  renderAll();
  ensurePdfFonts().then(()=>renderPreview()).catch(()=>{});

  const addOfferBtn = document.getElementById('addOffer');
  if(addOfferBtn) addOfferBtn.onclick=()=>{
    if(app.draft.items.length>=MAX_OFFERS){toast('الحد الأقصى 8 خيارات');return}
    app.draft.items.push(defaultOffer());
    persist();
    renderAll();
  };

  const grandTotalCb=document.getElementById('grandTotalToggle');
  if(grandTotalCb)grandTotalCb.addEventListener('change',()=>{
    app.draft.showGrandTotal=grandTotalCb.checked;
    persist();
    renderPreview();
    renderGrandTotalPreview();
  });

  ['saveQuote','saveQuoteTop'].forEach(id=>{
    const btn=document.getElementById(id);
    if(btn)btn.onclick=()=>saveCurrent(false);
  });

  const clearDraftBtn = document.getElementById('clearDraftBtn');
  if(clearDraftBtn) clearDraftBtn.onclick=()=>clearDraft(true);

  ['newQuote','newQuoteTop'].forEach(id=>{
    const btn=document.getElementById(id);
    if(btn)btn.onclick=newDraft;
  });

  ['printQuote','printTop'].forEach(id=>{
    const btn=document.getElementById(id);
    if(btn)btn.onclick=printQuotePdf;
  });

  ['downloadPdfQuote','downloadPdfTop'].forEach(id=>{
    const btn=document.getElementById(id);
    if(btn)btn.onclick=downloadQuotePdf;
  });

  const copyBtn = document.getElementById('copyText');
  if(copyBtn) copyBtn.onclick=copyQuote;

  const exportBtn = document.getElementById('exportBackup');
  if(exportBtn) exportBtn.onclick=exportBackup;

  const importBtn = document.getElementById('importBackup');
  if(importBtn) importBtn.onchange=e=>{
    const f=e.target.files[0];
    if(f)importBackup(f);
    e.target.value='';
  };

  const saveSettingsBtn = document.getElementById('saveSettings');
  if(saveSettingsBtn) saveSettingsBtn.onclick=saveSettings;

  const lockAppBtn = document.getElementById('lockApp');
  if(lockAppBtn) lockAppBtn.onclick=lockApp;

  updateScale();
  window.addEventListener('resize',updateScale);
  window.addEventListener('orientationchange',()=>setTimeout(updateScale,150));
  document.querySelectorAll('[data-mobile-tab]').forEach(b=>b.onclick=()=>setMobileTab(b.dataset.mobileTab));
  window.addEventListener('beforeunload',persist);
}

// SHA-256 with fallback for non-secure contexts (HTTP / local IP / file://)
function sha256Pure(str) {
  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }
  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  const K = [];
  const H = [];
  const isComposite = {};
  let primeCounter = 0;

  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (let i = 0; i < 300; i += candidate) {
        isComposite[i] = candidate;
      }
      H[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      K[primeCounter] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
      primeCounter++;
    }
  }

  const utf8 = [];
  for (let i = 0; i < str.length; i++) {
    let charcode = str.charCodeAt(i);
    if (charcode < 0x80) utf8.push(charcode);
    else if (charcode < 0x800) {
      utf8.push(0xc0 | (charcode >> 6), 0x80 | (charcode & 0x3f));
    } else if (charcode < 0xd800 || charcode >= 0xe000) {
      utf8.push(0xe0 | (charcode >> 12), 0x80 | ((charcode >> 6) & 0x3f), 0x80 | (charcode & 0x3f));
    } else {
      i++;
      charcode = 0x10000 + (((charcode & 0x3ff) << 10) | (str.charCodeAt(i) & 0x3ff));
      utf8.push(0xf0 | (charcode >> 18), 0x80 | ((charcode >> 12) & 0x3f), 0x80 | ((charcode >> 6) & 0x3f), 0x80 | (charcode & 0x3f));
    }
  }

  const bitLen = utf8.length * 8;
  utf8.push(0x80);
  while ((utf8.length % 64) !== 56) {
    utf8.push(0);
  }

  utf8.push(0, 0, 0, 0);
  utf8.push((bitLen >>> 24) & 0xff, (bitLen >>> 16) & 0xff, (bitLen >>> 8) & 0xff, bitLen & 0xff);

  const words = [];
  for (let i = 0; i < utf8.length; i += 4) {
    words.push((utf8[i] << 24) | (utf8[i + 1] << 16) | (utf8[i + 2] << 8) | utf8[i + 3]);
  }

  for (let i = 0; i < words.length; i += 16) {
    const w = words.slice(i, i + 16);
    const hash = H.slice(0);

    for (let j = 0; j < 64; j++) {
      if (j >= 16) {
        const s0 = rightRotate(w[j - 15], 7) ^ rightRotate(w[j - 15], 18) ^ (w[j - 15] >>> 3);
        const s1 = rightRotate(w[j - 2], 17) ^ rightRotate(w[j - 2], 19) ^ (w[j - 2] >>> 10);
        w[j] = (w[j - 16] + s0 + w[j - 7] + s1) | 0;
      }

      const S1 = rightRotate(hash[4], 6) ^ rightRotate(hash[4], 11) ^ rightRotate(hash[4], 25);
      const ch = (hash[4] & hash[5]) ^ (~hash[4] & hash[6]);
      const temp1 = (hash[7] + S1 + ch + K[j] + w[j]) | 0;
      const S0 = rightRotate(hash[0], 2) ^ rightRotate(hash[0], 13) ^ rightRotate(hash[0], 22);
      const maj = (hash[0] & hash[1]) ^ (hash[0] & hash[2]) ^ (hash[1] & hash[2]);
      const temp2 = (S0 + maj) | 0;

      hash[7] = hash[6];
      hash[6] = hash[5];
      hash[5] = hash[4];
      hash[4] = (hash[3] + temp1) | 0;
      hash[3] = hash[2];
      hash[2] = hash[1];
      hash[1] = hash[0];
      hash[0] = (temp1 + temp2) | 0;
    }

    for (let j = 0; j < 8; j++) {
      H[j] = (H[j] + hash[j]) | 0;
    }
  }

  let res = '';
  for (let i = 0; i < 8; i++) {
    res += (H[i] >>> 0).toString(16).padStart(8, '0');
  }
  return res;
}

async function sha256(value){
  try {
    if(window.crypto && crypto.subtle && typeof crypto.subtle.digest === 'function'){
      const data = new TextEncoder().encode(value);
      const digest = await crypto.subtle.digest('SHA-256', data);
      return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, '0')).join('');
    }
  } catch(e) {}
  return sha256Pure(value);
}

function unlockApp(){
  document.body.classList.remove('auth-locked');
  const gate=document.getElementById('authGate');
  if(gate)gate.remove();
  init();
}

function lockApp(){
  sessionStorage.removeItem('yanabea_auth_ok');
  localStorage.removeItem('yanabea_auth_ok');
  location.reload();
}

function setupAuth(){
  if(sessionStorage.getItem('yanabea_auth_ok')==='1'||localStorage.getItem('yanabea_auth_ok')==='1'){
    unlockApp();
    return;
  }
  const form=document.getElementById('authForm'),input=document.getElementById('authPassword'),remember=document.getElementById('authRemember'),error=document.getElementById('authError');
  if(!form||!input)return;
  setTimeout(()=>input.focus(),50);
  form.addEventListener('submit',async e=>{
    e.preventDefault();
    if(error)error.textContent='';
    const val = String(input.value || '').trim();
    try{
      const hash = await sha256(val);
      if(hash === AUTH_HASH){
        sessionStorage.setItem('yanabea_auth_ok','1');
        if(!remember||remember.checked){
          localStorage.setItem('yanabea_auth_ok','1');
        }else{
          localStorage.removeItem('yanabea_auth_ok');
        }
        unlockApp();
      }else{
        if(error)error.textContent='كلمة المرور غير صحيحة';
        input.value='';
        input.focus();
      }
    }catch(err){
      if(error)error.textContent='تعذر التحقق من كلمة المرور في هذا المتصفح';
    }
  });
}

setupAuth();

if('serviceWorker' in navigator && /^https?:$/.test(location.protocol)){
  window.addEventListener('load',async()=>{
    try{
      const reg=await navigator.serviceWorker.register('./sw.js');
      await reg.update();
    }catch(e){}
  });
}
